-- Safe bootstrap for fresh installations; existing non-empty schemas are baselined at version 1.
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, full_name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL DEFAULT 'CITIZEN', status VARCHAR(255) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reset_password_token VARCHAR(255), reset_password_token_expiry TIMESTAMP);
CREATE TABLE IF NOT EXISTS ration_cards (id BIGSERIAL PRIMARY KEY, ration_card_number VARCHAR(50) NOT NULL UNIQUE, card_type VARCHAR(20) NOT NULL, head_of_family VARCHAR(120), address TEXT, district VARCHAR(100), state VARCHAR(100), owner_email VARCHAR(150), status VARCHAR(30) NOT NULL DEFAULT 'PENDING', approval_status VARCHAR(30), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, application_number VARCHAR(50) UNIQUE, mobile VARCHAR(15), pincode VARCHAR(10), issued_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS ration_card_applications (id BIGSERIAL PRIMARY KEY, application_number VARCHAR(50) NOT NULL UNIQUE, applicant_name VARCHAR(120) NOT NULL, mobile VARCHAR(15), email VARCHAR(150), card_type VARCHAR(20), family_members INTEGER NOT NULL DEFAULT 0, family_members_data TEXT, address TEXT NOT NULL, district VARCHAR(100) NOT NULL, state VARCHAR(100), pincode VARCHAR(10), status VARCHAR(30) NOT NULL DEFAULT 'SUBMITTED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completion_status VARCHAR(30) NOT NULL DEFAULT 'IN_PROGRESS', rejection_reason TEXT, issued_ration_card_number VARCHAR(20));
CREATE TABLE IF NOT EXISTS family_members (id BIGSERIAL PRIMARY KEY, ration_card_id BIGINT NOT NULL REFERENCES ration_cards(id) ON DELETE CASCADE, member_id VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, age INTEGER NOT NULL CHECK (age >= 0), gender VARCHAR(20), relationship VARCHAR(60), rice_quota_kg NUMERIC(10,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS distribution_logs (id BIGSERIAL PRIMARY KEY, ration_card_id BIGINT REFERENCES ration_cards(id), member_id BIGINT REFERENCES family_members(id), quantity_kg NUMERIC(10,2) NOT NULL, distribution_date DATE NOT NULL, fps_id VARCHAR(50), transaction_status VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS grievances (id BIGSERIAL PRIMARY KEY, grievance_number VARCHAR(255) NOT NULL UNIQUE, applicant_name VARCHAR(255) NOT NULL, ration_card_number VARCHAR(255) NOT NULL, category VARCHAR(255) NOT NULL, contact_number VARCHAR(255) NOT NULL, description VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, submitted_by_email VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS onorc_portability (id BIGSERIAL PRIMARY KEY, reference_number VARCHAR(255) NOT NULL UNIQUE, ration_card_number VARCHAR(255) NOT NULL, home_state VARCHAR(255) NOT NULL, home_district VARCHAR(255) NOT NULL, destination_state VARCHAR(255) NOT NULL, destination_district VARCHAR(255) NOT NULL, fps_name VARCHAR(255), fps_code VARCHAR(255), status VARCHAR(255) NOT NULL, requested_by VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, event_type VARCHAR(80) NOT NULL, actor_email VARCHAR(150), target_reference VARCHAR(100), outcome VARCHAR(30) NOT NULL, details TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_log (id BIGSERIAL PRIMARY KEY, notification_key VARCHAR(180) NOT NULL UNIQUE, recipient_email VARCHAR(150), notification_type VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, last_error VARCHAR(300), next_attempt_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at TIMESTAMP);
